// Runs when workflow 01 or 02 fails. Builds a stable eventId from the
// failed execution so the Convex error log stays idempotent too, then
// signs the payload like every other Convex callback.

function sign(rawBody) {
  const secret = $env.LENDLOOP_WEBHOOK_SECRET;
  if (!secret) throw new Error('LENDLOOP_WEBHOOK_SECRET is not set in the n8n environment.');
  return require('crypto').createHmac('sha256', secret).update(rawBody, 'utf8').digest('hex');
}
function convexUrl(path) {
  const base = ($env.CONVEX_SITE_URL || '').replace(/\/$/, '');
  if (!base) throw new Error('CONVEX_SITE_URL is not set in the n8n environment (use the .convex.site URL).');
  return base + path;
}
const data = $input.first().json;
const executionId = (data.execution && data.execution.id) || 'unknown';
const workflowId = (data.workflow && data.workflow.id) || 'unknown';
const workflowName = (data.workflow && data.workflow.name) || 'unknown workflow';
const message = (data.execution && data.execution.error && data.execution.error.message) || 'unknown error';
const rawBody = JSON.stringify({
  eventId: 'error:' + workflowId + ':' + executionId,
  detail: ('Workflow "' + workflowName + '" execution ' + executionId + ' failed: ' + message).slice(0, 480),
});
return [{ json: {
  rawBody,
  signature: 'sha256=' + sign(rawBody),
  url: convexUrl('/n8n/error-logged'),
} }];
